const MS_PER_DAY = 86_400_000;

export function daysSinceRoast(roastedOn: string, today: Date): number {
  const roast = Date.parse(`${roastedOn}T00:00:00Z`);
  if (Number.isNaN(roast)) throw new Error(`invalid roast date: ${roastedOn}`);
  const dayStart = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
  return Math.floor((dayStart - roast) / MS_PER_DAY);
}

export function isFresh(roastedOn: string, today: Date): boolean {
  return daysSinceRoast(roastedOn, today) <= 14;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { daysSinceRoast, isFresh } from "../src/freshness.ts";

test("day 0: roasted today is 0 days old and fresh", () => {
  const today = new Date("2026-10-12T09:30:00Z");
  assert.equal(daysSinceRoast("2026-10-12", today), 0);
  assert.equal(isFresh("2026-10-12", today), true);
});

test("day 14: still fresh (inclusive)", () => {
  const today = new Date("2026-10-26T18:00:00Z");
  assert.equal(daysSinceRoast("2026-10-12", today), 14);
  assert.equal(isFresh("2026-10-12", today), true);
});

test("day 15: no longer fresh", () => {
  const today = new Date("2026-10-27T06:00:00Z");
  assert.equal(daysSinceRoast("2026-10-12", today), 15);
  assert.equal(isFresh("2026-10-12", today), false);
});
